        if(kind=="speech.started"){const auto it=pendingReplies_.find(e.value("reply_id",std::string{}));if(it!=pendingReplies_.end()){const auto pending=it->second;pendingReplies_.erase(it);beginBubble(pending.at("text"),pending.at("reply_id"));}}
        if(kind=="speech.failed"){const auto it=pendingReplies_.find(e.value("reply_id",std::string{}));if(it!=pendingReplies_.end()){const auto pending=it->second;pendingReplies_.erase(it);beginBubble(pending.at("text"),pending.at("reply_id"));}}
