    bool restore(const PluginJson& value)override{if(!value.is_object())return false;try{std::lock_guard lock(mutex_);x_=number(value,"x",0.1,0,1)*(width_-size_);y_=number(value,"y",0.5,0,1)*(height_-size_);constrainPoint(x_,y_);targetX_=x_;targetY_=y_;restToken_.clear();movementToken_.clear();cancelPose();dragMotion_.reset();pointer_.cancel();dragged_=false;dropping_=false;pickupSide_=false;postponeRoam();visible_=value.value("visible",true);state_="idle";return true;}catch(...){return false;}}
